_PASS = {"farmer": ["PASS"], "hands": [], "market": []}


def agent(obs, config=None):
    try:
        step = int(obs.get("step", 0) or 0)
        if step < len(_OPEN):
            act = _OPEN[step]
            # the tape's hand list is sized for ITS crew; trim to ours so a
            # positional hands list never addresses a hand we do not have
            hands = obs["farms"][obs["player"]].get("hands", [])
            a = dict(act)
            a["hands"] = (act.get("hands") or [])[: len(hands)]
            return a
        return _net_agent(obs, config)
    except Exception:
        return _PASS
